import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.DHNVigYl.js";const n="/assets/Theengs_decoder_iot_chain.B3IZm5h9.jpg",i="/assets/Theengs_decoder.Bo0FJ1EP.jpg",f=JSON.parse('{"title":"Theengs BLE decoder","description":"","frontmatter":{"title":"Theengs BLE decoder"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788361043000}'),s={name:"index.md"};function d(l,e,h,c,p,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="theengs-ble-decoder" tabindex="-1">Theengs BLE decoder <a class="header-anchor" href="#theengs-ble-decoder" aria-label="Permalink to &quot;Theengs BLE decoder&quot;">​</a></h1><p>Theengs Decoder project aims to provide an efficient, portable and lightweight library for BLE Internet of Things messages decoding.</p><p><img src="'+n+'" alt="Iot"></p><p>Sensors and devices use chains of data to communicate to gateways, computers, servers. Enabling them to have lightweight and fast communication. On the other hand we have a huge diversity of communication methods, resulting in the sensors or devices being closed to one ecosystem or a few.</p><p>Theengs Decoder library translates these data chains into human readable data leveraging the well known data interchange format JSON. This format can easily be integrated into different systems or software.</p><p><img src="'+i+'" alt="Overview"></p><p>It&#39;s also a simplified way of defining the thing properties and how to decode these.</p><p>Theengs Decoder supports the decoding of <a href="./devices/devices.html">more than 140 Bluetooth devices</a>.</p><p>Theengs Decoder can be used on memory constraint environments like micro controllers (ESP32, ESP8266, Arduino), on a PC or on a Unix server. Unit testing assures that the modification done on the library doesn&#39;t affect previous capabilities.</p><p>In a few words:</p><ul><li>Light</li><li>Portable</li><li>Expandable</li><li>Interoperable</li></ul><p>Projects using the Theengs Decoder library</p><ul><li><a href="https://docs.openmqttgateway.com/" target="_blank" rel="noreferrer">OpenMQTTGateway</a> - A BLE to MQTT bridge running on ESP8266, ESP32 or Arduino boards.</li><li><a href="https://gateway.theengs.io/" target="_blank" rel="noreferrer">Theengs Gateway</a> - A Python-based BLE to MQTT bridge running on Raspberry Pi, Windows or Linux.</li><li><a href="https://github.com/theengs/explorer" target="_blank" rel="noreferrer">Theengs Explorer</a> - A text user interface to discover BLE devices, showing their raw advertisement alongside the decoded data; running on Linux, Windows or macOS.</li><li><a href="https://app.theengs.io/" target="_blank" rel="noreferrer">Theengs App</a> - A paid app for Android and iOS/iPadOS phones and tablets displaying decoded BLE sensor data and optionally acting as a BLE to MQTT bridge.</li><li><a href="https://github.com/matthias-bs/BresserWeatherSensorLW" target="_blank" rel="noreferrer">BresserWeatherSensorLW</a> - Bresser 868 MHz Weather Sensor Radio Receiver based on ESP32/RP2040 and SX1262/SX1276 — sends data to a LoRaWAN Network.</li><li><a href="https://github.com/BlackLight/platypush" target="_blank" rel="noreferrer">Platypush</a> - A versatile and extensible platform for home and life automation with hundreds of supported integrations.</li><li><a href="https://github.com/elebree/fritzgate" target="_blank" rel="noreferrer">FritzGate</a> - Bind thermostats connected to a FRITZ!Box to third-party Bluetooth thermometers.</li></ul><div class="warning custom-block"><p class="custom-block-title">Note</p><p>The material and information contained in this documentation is for general information purposes only. You should not rely upon the material or information on this documentation as a basis for making any business, legal or any other decisions. There is no warranty given on this documentation content. If you decide to follow the information and materials given it is at your own risk. I will not be liable for any false, inaccurate, inappropriate or incomplete information presented on this website.</p></div>',14)])])}const u=t(s,[["render",d]]);export{f as __pageData,u as default};
